{
  "name": "Expense Report Processing",
  "resources": [
    {
      "name": "Employee",
      "capacity": 1,
      "resource_type": "human"
    },
    {
      "name": "Supervisor",
      "capacity": 1,
      "resource_type": "human"
    },
    {
      "name": "Accounts System",
      "capacity": 1,
      "resource_type": "system"
    }
  ],
  "events": [
    {
      "id": "start_1",
      "name": "Expense Report Received",
      "event_position": "start",
      "trigger_type": "message",
      "message_name": "Expense Report"
    },
    {
      "id": "timer_7d",
      "name": "7 Days Timeout",
      "event_position": "intermediate",
      "trigger_type": "timer",
      "message_name": null
    },
    {
      "id": "timer_30d",
      "name": "30 Days Timeout",
      "event_position": "intermediate",
      "trigger_type": "timer",
      "message_name": null
    },
    {
      "id": "end_reimbursed",
      "name": "Reimbursement Completed",
      "event_position": "end",
      "trigger_type": "none",
      "message_name": null
    },
    {
      "id": "end_rejected",
      "name": "Expense Report Rejected",
      "event_position": "end",
      "trigger_type": "none",
      "message_name": null
    },
    {
      "id": "end_cancelled",
      "name": "Process Cancelled",
      "event_position": "end",
      "trigger_type": "none",
      "message_name": null
    }
  ],
  "tasks": [
    {
      "id": "task_check_account",
      "name": "Check if Employee Account Exists",
      "bpmn_type": "bpmn:ServiceTask",
      "resource_name": "Accounts System",
      "duration": {
        "distribution": "fixed",
        "value": 1.0,
        "unit": "minutes",
        "is_placeholder": true,
        "source": "default_missing_duration"
      },
      "is_loop": false,
      "input_data_ids": ["data_expense_report"],
      "output_data_ids": []
    },
    {
      "id": "task_create_account",
      "name": "Create New Account",
      "bpmn_type": "bpmn:ServiceTask",
      "resource_name": "Accounts System",
      "duration": {
        "distribution": "fixed",
        "value": 1.0,
        "unit": "minutes",
        "is_placeholder": true,
        "source": "default_missing_duration"
      },
      "is_loop": false,
      "input_data_ids": [],
      "output_data_ids": []
    },
    {
      "id": "task_review_auto",
      "name": "Review Report Amount for Automatic Approval",
      "bpmn_type": "bpmn:ServiceTask",
      "resource_name": "Accounts System",
      "duration": {
        "distribution": "fixed",
        "value": 1.0,
        "unit": "minutes",
        "is_placeholder": true,
        "source": "default_missing_duration"
      },
      "is_loop": false,
      "input_data_ids": ["data_expense_report"],
      "output_data_ids": []
    },
    {
      "id": "task_supervisor_approval",
      "name": "Supervisor Review and Approval",
      "bpmn_type": "bpmn:UserTask",
      "resource_name": "Supervisor",
      "duration": {
        "distribution": "fixed",
        "value": 1.0,
        "unit": "minutes",
        "is_placeholder": true,
        "source": "default_missing_duration"
      },
      "is_loop": false,
      "input_data_ids": ["data_expense_report"],
      "output_data_ids": []
    },
    {
      "id": "task_send_rejection",
      "name": "Send Rejection Notice by Email",
      "bpmn_type": "bpmn:ServiceTask",
      "resource_name": "Accounts System",
      "duration": {
        "distribution": "fixed",
        "value": 1.0,
        "unit": "minutes",
        "is_placeholder": true,
        "source": "default_missing_duration"
      },
      "is_loop": false,
      "input_data_ids": [],
      "output_data_ids": ["data_rejection_notice"]
    },
    {
      "id": "task_reimburse",
      "name": "Deposit Reimbursement to Bank Account",
      "bpmn_type": "bpmn:ServiceTask",
      "resource_name": "Accounts System",
      "duration": {
        "distribution": "fixed",
        "value": 1.0,
        "unit": "minutes",
        "is_placeholder": true,
        "source": "default_missing_duration"
      },
      "is_loop": false,
      "input_data_ids": [],
      "output_data_ids": []
    },
    {
      "id": "task_send_in_progress",
      "name": "Send Approval in Progress Email",
      "bpmn_type": "bpmn:ServiceTask",
      "resource_name": "Accounts System",
      "duration": {
        "distribution": "fixed",
        "value": 1.0,
        "unit": "minutes",
        "is_placeholder": true,
        "source": "default_missing_duration"
      },
      "is_loop": false,
      "input_data_ids": [],
      "output_data_ids": ["data_in_progress_email"]
    },
    {
      "id": "task_send_cancellation",
      "name": "Send Email Cancellation Notice and Request Re-submission",
      "bpmn_type": "bpmn:ServiceTask",
      "resource_name": "Accounts System",
      "duration": {
        "distribution": "fixed",
        "value": 1.0,
        "unit": "minutes",
        "is_placeholder": true,
        "source": "default_missing_duration"
      },
      "is_loop": false,
      "input_data_ids": [],
      "output_data_ids": ["data_cancellation_notice"]
    }
  ],
  "gateways": [
    {
      "id": "gw_account_exists",
      "name": "Does Employee Have an Account?",
      "gateway_type": "exclusive",
      "branch_probabilities": null,
      "branch_conditions": [
        {
          "flow_id": "flow_to_create_acc",
          "condition": "No"
        },
        {
          "flow_id": "flow_to_review",
          "condition": "Yes"
        }
      ]
    },
    {
      "id": "gw_merge_account",
      "name": "Merge Account Check",
      "gateway_type": "exclusive",
      "branch_probabilities": null,
      "branch_conditions": null
    },
    {
      "id": "gw_amount_check",
      "name": "Amount Threshold Check",
      "gateway_type": "exclusive",
      "branch_probabilities": null,
      "branch_conditions": [
        {
          "flow_id": "flow_auto_approved",
          "condition": "Under $200"
        },
        {
          "flow_id": "flow_requires_supervisor",
          "condition": "Equal to or over $200"
        }
      ]
    },
    {
      "id": "gw_supervisor_decision",
      "name": "Supervisor Decision",
      "gateway_type": "exclusive",
      "branch_probabilities": null,
      "branch_conditions": [
        {
          "flow_id": "flow_sup_approved",
          "condition": "Approved"
        },
        {
          "flow_id": "flow_sup_rejected",
          "condition": "Rejected"
        }
      ]
    },
    {
      "id": "gw_merge_approval",
      "name": "Merge Approval Path",
      "gateway_type": "exclusive",
      "branch_probabilities": null,
      "branch_conditions": null
    }
  ],
  "sequence_flows": [
    {
      "id": "flow_1",
      "source_id": "start_1",
      "target_id": "task_check_account",
      "condition_name": null
    },
    {
      "id": "flow_2",
      "source_id": "task_check_account",
      "target_id": "gw_account_exists",
      "condition_name": null
    },
    {
      "id": "flow_to_create_acc",
      "source_id": "gw_account_exists",
      "target_id": "task_create_account",
      "condition_name": "No"
    },
    {
      "id": "flow_to_review",
      "source_id": "gw_account_exists",
      "target_id": "gw_merge_account",
      "condition_name": "Yes"
    },
    {
      "id": "flow_created_acc_to_merge",
      "source_id": "task_create_account",
      "target_id": "gw_merge_account",
      "condition_name": null
    },
    {
      "id": "flow_merge_to_review",
      "source_id": "gw_merge_account",
      "target_id": "task_review_auto",
      "condition_name": null
    },
    {
      "id": "flow_review_to_gw",
      "source_id": "task_review_auto",
      "target_id": "gw_amount_check",
      "condition_name": null
    },
    {
      "id": "flow_auto_approved",
      "source_id": "gw_amount_check",
      "target_id": "gw_merge_approval",
      "condition_name": "Under $200"
    },
    {
      "id": "flow_requires_supervisor",
      "source_id": "gw_amount_check",
      "target_id": "task_supervisor_approval",
      "condition_name": "Equal to or over $200"
    },
    {
      "id": "flow_sup_to_gw",
      "source_id": "task_supervisor_approval",
      "target_id": "gw_supervisor_decision",
      "condition_name": null
    },
    {
      "id": "flow_sup_approved",
      "source_id": "gw_supervisor_decision",
      "target_id": "gw_merge_approval",
      "condition_name": "Approved"
    },
    {
      "id": "flow_sup_rejected",
      "source_id": "gw_supervisor_decision",
      "target_id": "task_send_rejection",
      "condition_name": "Rejected"
    },
    {
      "id": "flow_rejection_to_end",
      "source_id": "task_send_rejection",
      "target_id": "end_rejected",
      "condition_name": null
    },
    {
      "id": "flow_approval_to_reimburse",
      "source_id": "gw_merge_approval",
      "target_id": "task_reimburse",
      "condition_name": null
    },
    {
      "id": "flow_reimburse_to_end",
      "source_id": "task_reimburse",
      "target_id": "end_reimbursed",
      "condition_name": null
    },
    {
      "id": "flow_timer_7d",
      "source_id": "timer_7d",
      "target_id": "task_send_in_progress",
      "condition_name": null
    },
    {
      "id": "flow_timer_30d",
      "source_id": "timer_30d",
      "target_id": "task_send_cancellation",
      "condition_name": null
    },
    {
      "id": "flow_cancellation_to_end",
      "source_id": "task_send_cancellation",
      "target_id": "end_cancelled",
      "condition_name": null
    }
  ],
  "pools": [],
  "message_flows": [],
  "data_objects": [
    {
      "id": "data_expense_report",
      "name": "Expense Report"
    },
    {
      "id": "data_rejection_notice",
      "name": "Rejection Notice Email"
    },
    {
      "id": "data_in_progress_email",
      "name": "Approval In Progress Email"
    },
    {
      "id": "data_cancellation_notice",
      "name": "Email Cancellation Notice"
    }
  ],
  "data_stores": [],
  "inter_arrival_time": {
    "distribution": "fixed",
    "value": 1.0,
    "unit": "minutes",
    "is_placeholder": true,
    "source": "default_missing_duration"
  },
  "simulation_duration": null,
  "simulation_duration_unit": "minutes"
}
